DATA_SRC_NM = #{name}, DB_TYPE_DVCD = #{dbType}, JDBC_URL = #{jdbcUrl}, DB_USER_ID = #{dbUser}, DB_ENC_PW = #{encPw}, MINI_POOL_CNT = #{poolMin}, MAX_POOL_CNT = #{poolMax}, QUERY_TIMEOUT_SEC = #{queryTimeoutSec}, USE_YN = #{useYn}, MODID = #{modid}, MODDT = SYSTIMESTAMP
